select management_agent_scan('10000000-0000-4000-8000-000000000001');
select is((select count(*)::integer from management_cases),1,'observe creates one durable case');
select is((select count(*)::integer from notifications),0,'observe never sends new notifications');
select is((select count(*)::integer from management_notion_outbox),0,'observe never queues Notion');
do $$ begin for i in 1..100 loop perform management_agent_scan('10000000-0000-4000-8000-000000000001'); end loop; end $$;
select is((select count(*)::integer from management_cases),1,'100 scans deduplicate cases');
select is((select count(*)::integer from management_case_events),1,'100 scans preserve one detection');
update tenant_settings set data=jsonb_set(data,'{notifications,managementAgent,mode}','"active"') where tenant_id='10000000-0000-4000-8000-000000000001';
select management_agent_scan('10000000-0000-4000-8000-000000000001');
select is((select count(*)::integer from notifications),2,'activation notifies counselor and principal once');
select is((select count(*)::integer from management_notion_outbox),1,'activation queues one Notion notice');
select management_agent_scan('10000000-0000-4000-8000-000000000001');
select is((select count(*)::integer from notifications),2,'second active scan does not duplicate notifications');
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000012',false);
select lives_ok($$select management_case_command(id,version,'acknowledge') from management_cases$$,'counselor can acknowledge own case');
select is((select status from management_cases),'in_progress','acknowledgement is not resolution');
select throws_ok($$select management_case_command(id,1,'submit','contacted','가상 학생 보호자 연락 완료 기록입니다') from management_cases$$,'P0001',null,'stale version cannot overwrite');
select throws_ok($$select management_case_command(id,null,'acknowledge') from management_cases$$,'P0001',null,'null version cannot bypass concurrency');
select throws_ok($$select management_case_command(id,version,'submit','retry','가상 학생 재연락 예정입니다',null) from management_cases$$,'P0001',null,'retry requires next date');
select lives_ok($$select management_case_command(id,version,'submit','contacted','가상 학생 보호자에게 후속 내용을 안내했습니다') from management_cases$$,'counselor submits outcome');
select is((select status from management_cases),'waiting_review','submission waits for verification');
select throws_ok($$select management_case_command(id,version,'verify',null,'원본과 처리 기록을 확인한 가상 근거입니다') from management_cases$$,'42501',null,'counselor cannot verify own completion');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000011',false);
select throws_ok($$select management_case_command(id,version,'verify',null,'원본과 처리 기록을 확인한 가상 근거입니다') from management_cases$$,'P0001',null,'unchecked source prevents verified closure');
reset role;
update student_consultations set follow_up_done=true where tenant_id='10000000-0000-4000-8000-000000000001';
select management_agent_scan('10000000-0000-4000-8000-000000000001');
select is((select status from management_cases),'waiting_review','source done is not automatically verified');
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000011',false);
select lives_ok($$select management_case_command(id,version,'verify',null,'후속 상담 원본과 연락 결과를 직접 확인했습니다') from management_cases$$,'principal verifies with source and reason');
select is((select status from management_cases),'resolved','verified state persisted');
reset role;
update student_consultations set follow_up_done=false where tenant_id='10000000-0000-4000-8000-000000000001';
select management_agent_scan('10000000-0000-4000-8000-000000000001');
select is((select status from management_cases),'open','unchecking source reopens episode');
select is((select episode from management_cases),2,'recurrence has distinct episode');
select ok((select result_note is null and verification_note is null from management_cases),'old evidence cannot close recurrence');
select is((select count(*)::integer from management_notion_outbox),1,'all updates share one Notion delivery record');
